(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fr"] = {"ui":{"skip":"Aller au contenu","back":"← Retour à AI-gile","lang.button":"Langue : {name}","lang.dialog":"Choisis une langue","lang.search":"Chercher une langue","lang.none":"Aucune langue ne correspond","lang.notYet":"{name} n'est pas encore traduit","theme.aria":"Passer du thème clair au thème sombre","theme.toLight":"Passer au thème clair","theme.toDark":"Passer au thème sombre","index.title":"AI-gile : ton équipe de dev IA, sur un seul tableau","index.description":"AI-gile est un tableau kanban pour les équipes de code IA. Elles travaillent pendant que tu dors ; tu reçois une petite pile de choses à trancher, tester et accepter.","hero.logoAlt":"Icône du tableau AI-gile","hero.h1.html":"Ton équipe de dev IA, sur un seul&nbsp;tableau.","hero.alpha":"🐣 Pré-alpha fermée","hero.alphaTitle":"Tôt et inachevé : merci de l'essayer !","hero.lede":"Elles construisent pendant que tu dors. Au réveil, une petite pile t'attend : quelques questions, quelques choses à tester, un ou deux diamants violets. Un clic, c'est accepté, et retour à ton café.","dl.windows":"Appli Windows","dl.browser":"L'utiliser dans le navigateur","dl.soon":"Bientôt disponible","dl.notify":"🔔 Préviens-moi à l'ouverture","dl.notifySmall":"Alpha ou bêta","hero.secondary":"De l'agile, mais l'équipe n'a jamais besoin du café de la réunion debout. (Elle fait quand même la réunion.)","pitch.h2":"AI-gile en autant de mots que tu veux","pitch.lede":"Choisis une longueur, d'un mot à 144. Chaque longueur est sa propre description, écrite pour cette taille. Fais glisser le curseur ou utilise les flèches du clavier.","pitch.rangeLabel":"Longueur en mots","pitch.dice":"🎲 une autre version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} lettre","pitch.letters.other":"{n} lettres","pitch.chars.one":"{n} caractère","pitch.chars.other":"{n} caractères","count.line.html.one":"{n} carte sur le tableau en ce moment","count.line.html.other":"{n} cartes sur le tableau en ce moment","features.aria":"Ce qu'il fait","f.pile.h":"Une seule pile pour toi","f.pile.html":"<b>Pour toi</b> réunit tout ce qui t'attend, tous projets confondus : des questions, des choses à tester, des tâches que seul un humain peut faire. Ta file te dit ce qui vient ensuite et combien de temps ça prend.","f.sleep.h":"Des équipes qui travaillent pendant que tu dors","f.sleep.p":"Chaque projet a un chef et une équipe d'agents IA. Commente une carte et l'équipe se réveille, fait le travail, puis te le rend avec des étapes qu'un humain fatigué peut suivre.","f.tester.h":"Un testeur IA vérifie d'abord","f.tester.p":"Avant que quoi que ce soit n'arrive jusqu'à toi, un testeur suit les étapes dans une copie de l'appli et montre ce qu'il a vu, avec une capture d'écran. Feuillette celles qui sont passées et accepte d'un clic.","f.proof.h":"Des preuves, pas des promesses","f.proof.p":"Chaque remise montre ce qui a changé : les fichiers, le diff, les captures d'écran. Plus besoin d'ouvrir chaque appli pour savoir si c'est fini.","f.chat.h":"Discute avec tes chefs","f.chat.p":"Une colonne façon Discord : une icône par projet, des diamants violets pour ce qui a besoin de toi. Envoie une idée à un chef ; il en fait des cartes et un plan, avec un bouton ✅ Go.","f.tidy.h":"Se range tout seul","f.tidy.p":"Les cartes liées fusionnent, les titres confus sont corrigés, et un contrôle des tokens garde le code léger. Moins de choses entre lesquelles jongler, moins à penser.","f.private.h":"À toi, sur ton ordinateur","f.private.li1":"Le tableau tourne sur ta propre machine et ne répond qu'à toi.","f.private.li2":"Les messages privés entre personnes sont chiffrés de bout en bout.","f.private.li3":"Pas de compte, pas de traceurs, pas de cookies.","f.lang.h":"Dans ta langue","f.lang.p":"Plus de 120 langues, du néerlandais, du gallois et du japonais au pirate, à Yoda et au klingon, avec un retour rapide à l'anglais pour les mots de développeur.","tl.aria":"Chronologie, de la première conversation à la feuille de route","tl.h2":"De la première discussion à la suite","tl.lede":"De vraies dates et heures, dans ton fuseau horaire. Après aujourd'hui, c'est le plan, sans date promise.","tl.today":"Aujourd'hui","tl.planned":"prévu","tl.cards.one":"{n} carte","tl.cards.other":"{n} cartes","join.h2":"Rejoins-nous","join.lede":"AI-gile est construit par un petit humain et un grand nombre d'agents patients. Pour l'instant c'est privé, en alpha fermée entre amis. Envie d'essayer quand ça s'ouvrira ?","join.btn":"Je suis intéressé","join.small":"On t'écrira, rien d'autre","footer.tag":"AI-gile. Pas de traceurs, pas de cookies, pas de café de réunion debout.","footer.licence":"Licence professionnelle","footer.status":"État","form.sending":"Envoi…","form.failed":"Ça n'a pas marché : réessaie plus tard.","form.offline":"Impossible de joindre AI-gile : réessaie plus tard.","interest.title":"AI-gile : préviens-moi à l'ouverture de l'alpha","interest.description":"Laisse ton e-mail pour savoir quand l'alpha ou la bêta fermée d'AI-gile s'ouvre.","interest.h1":"🔔 Préviens-moi à l'ouverture","interest.lede":"AI-gile est en pré-alpha fermée. Laisse ton e-mail et on t'écrira une seule fois, quand il y aura une place pour toi.","interest.email":"Ton e-mail","interest.which":"Quel test ?","interest.alpha":"Alpha fermée : tôt, brut, beaucoup de changements","interest.beta":"Bêta : plus stable, plus tard","interest.both":"L'une ou l'autre, la première qui ouvre","interest.submit":"Inscris-moi sur la liste","interest.thanks":"Merci ! Tu es sur la liste.","interest.kept":"Seuls ton e-mail et le test choisi sont conservés, pour cette liste uniquement. Pas de lettre d'information, pas de traceurs.","licence.title":"AI-gile : licence professionnelle","licence.description":"Tu utilises AI-gile dans ton activité ? Demande une licence professionnelle gratuite.","licence.h1":"📜 Licence professionnelle","licence.lede":"Tu utilises AI-gile au travail ? Dis-nous qui tu es et ce que tu fais. Si ça fait du bien, la licence est gratuite.","licence.company":"Entreprise","licence.website":"Site web","licence.what":"Ce que tu fais","licence.how":"En quoi ça aide le monde","licence.email":"E-mail","licence.submit":"Envoyer la demande","licence.thanks":"Merci ! On te répondra par e-mail.","status.title":"État d'AI-gile","status.h1":"État d'AI-gile","status.quiet":"Tout est calme","status.checking":"Vérification…","status.offline":"Impossible de joindre le service d'état pour le moment (nouvel essai en cours)","status.updated":"mis à jour {ago}","status.justNow":"à l'instant","status.min":"il y a {n} min","status.hours":"il y a {n} h","status.days":"il y a {n} j"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Délégué."]},{"n":2,"texts":["Kanban robotique.","Agents, organisés.","Idées, réalisées."]},{"n":3,"texts":["Kanban pour robots.","Tes idées deviennent fonctionnalités.","Kanban d'agents gratuit."]},{"n":5,"texts":["Un tableau piloté par des agents.","Tu écris, les agents construisent.","Gratuit, local, testé, un peu fou."]},{"n":8,"texts":["Un kanban gratuit où travaillent des agents IA.","Écris une idée. Les agents construisent. Tu acceptes.","L'agile pour un humain et plein de robots patients."]},{"n":13,"texts":["Un tableau kanban sur ton ordinateur, où des agents IA prennent les cartes en charge.","Écris une idée. Une équipe d'agents la construit. Un testeur la vérifie.","Gratuit, sans compte, sans traceurs : un tableau, des robots, et toi aux commandes."]},{"n":21,"texts":["AI-gile est un tableau kanban pour travailler avec des agents de code IA. Ils prennent les cartes ; toi, tu testes et tu acceptes.","Chaque projet reçoit un chef et une équipe d'agents IA. Commente n'importe quelle carte et l'équipe se met au travail.","Un tableau de tâches perso et gratuit, qui tourne sur ton propre ordinateur. Les ouvriers sont des robots. Celui qui dit oui, c'est toi."]},{"n":34,"texts":["Tu poses tes idées sur un tableau. Une équipe d'agents IA les transforme en fonctionnalités qui marchent, les teste et te les rend avec des étapes à essayer. Rien n'est terminé tant que tu ne l'as pas dit.","AI-gile est un tableau kanban fait maison, que Rich a construit avec beaucoup d'aide des agents qu'il gère maintenant. Il est gratuit, tourne sur ton ordinateur, et se partage entre amis, il ne se vend pas.","Imagine un tableau kanban tout simple, avec des colonnes du Backlog jusqu'à Terminé, sauf que les cartes sont prises par des agents IA. Ils donnent des nouvelles, posent des questions quand ils bloquent, et attendent toujours ton feu vert."]},{"n":55,"texts":["AI-gile est un tableau kanban dont l'équipe est faite d'agents IA. Chaque projet a un chef qui planifie le travail et des aides qui le construisent. Quand une fonctionnalité est prête, un testeur IA l'essaie et prend une capture d'écran, puis elle arrive dans ta pile. Accepte-la, ou commente et ils la retravaillent.","Tout a commencé comme la façon qu'avait une personne de suivre plein de sessions de code IA en même temps, puis c'est devenu un vrai tableau. Il tourne sur ta machine, ne demande aucun compte et n'a aucun traceur. Il est gratuit pour les amis et les curieux. Il est aussi inachevé : attends-toi à des aspérités et à quelques surprises.","Voici la version honnête. C'est toujours à toi d'avoir les idées, et toujours à toi de vérifier les résultats. Ce qu'AI-gile fait, c'est tout ce qu'il y a entre les deux : il garde les cartes en ordre, réveille le bon agent quand tu commentes, montre exactement ce qui a changé, et range tout ça dans une seule petite pile pour toi."]},{"n":89,"texts":["AI-gile est un tableau kanban gratuit que tu fais tourner sur ton propre ordinateur. Au lieu de personnes, chaque projet a une équipe d'agents IA : un chef qui transforme tes idées en cartes et en plan, et des aides qui prennent les cartes par ordre de priorité. Quand quelque chose est construit, un testeur IA suit les étapes de test et te montre ce qu'il a vu. Ensuite ça attend dans une pile appelée Pour toi. Tu l'acceptes, ou tu commentes et l'équipe retente sa chance. Rien n'arrive jamais dans Terminé sans toi.","Quelques fonctions que tu n'attends peut-être pas. Une veille de nuit garde la colonne À faire bien garnie pendant que tu dors, en choisissant des cartes qui n'ont pas besoin de ta réponse. Un compteur de tokens montre combien les agents ont consommé aujourd'hui et cette semaine, et le mode sans tokens leur dit d'arrêter de dépenser. Tu peux écrire à tes amis, et les messages privés sont chiffrés de bout en bout. Le tableau parle environ 120 langues, dont le néerlandais, le flamand, le pirate et le klingon. Rien de tout ça ne coûte un centime, et personne n'essaie de te le vendre non plus.","AI-gile est un petit projet personnel, pas une entreprise. Rich voulait s'occuper de plusieurs projets de code IA sans ouvrir chaque appli pour aller voir, alors lui et les agents ont construit un tableau pour ça, puis s'en sont servis pour construire le reste. Il est en pré-alpha fermée, ce qui veut dire qu'il fonctionne, à peu près, pour une poignée d'amis. Il n'y a ni page de tarifs, ni lettre d'information, ni plan de croissance. Si ça te semble utile, tu pourras demander à l'essayer quand il s'ouvrira un peu plus."]},{"n":144,"texts":["AI-gile est un tableau kanban pour un humain et beaucoup d'agents IA. Il tourne sur ton propre ordinateur et il est entièrement gratuit. Tu ajoutes des projets, et chaque projet reçoit un chef et une petite équipe. Tu discutes avec le chef, un peu comme sur Discord, et tu décris une idée ; le chef en fait des cartes et un plan, puis attend que tu appuies sur Go. L'équipe déroule les cartes par ordre de priorité, avec une ligne de commande toute simple pensée pour les modèles de langage. Avant que quoi que ce soit ne te revienne, un testeur IA suit les étapes dans une copie de l'appli et joint une capture d'écran. Le travail terminé arrive dans ta pile avec les fichiers modifiés et le diff. Tu l'acceptes, ou tu laisses un commentaire et l'équipe se réveille et réessaie. Toi seul peux déplacer une carte vers Terminé.","Une journée avec AI-gile, en gros. Le soir, tu laisses quelques commentaires : ce bouton est mal placé, cette liste devrait être triée, on pourrait avoir un mode sombre. Tu vas te coucher. Les agents lisent les commentaires, font les changements, les testent et te les rendent. Si À faire se vide, la veille de nuit le remplit depuis le backlog avec des cartes qui n'ont pas besoin de ta réponse. Le matin, il y a une seule petite pile : deux ou trois questions et quelques choses à essayer, chacune avec des étapes qu'une personne ensommeillée peut suivre et une capture d'écran qui prouve que ça marche. Tu cliques, tu acceptes les bonnes et tu renvoies le reste. Un compteur de tokens montre ce que tout ça a coûté, et le mode sans tokens est là pour les semaines maigres. Ensuite tu prends ton petit-déjeuner, ce que les agents ne savent pas encore faire pour toi.","D'abord, ce qu'AI-gile n'est pas. Ce n'est pas une start-up, ce n'est pas à vendre, et personne ne récolte tes données. C'est un tableau gratuit qui tourne sur ton ordinateur, sans compte, sans traceurs et sans cookies. Ce que c'est : un endroit bien rangé pour voir d'un coup tous tes projets de code IA, avec une équipe d'agents qui s'occupe des cartes et toi qui prends les décisions. Il fusionne les cartes liées, corrige les titres confus, et surveille que le code reste léger. Il parle environ 120 langues, du néerlandais et du flamand jusqu'au pirate et au klingon. Les amis peuvent s'écrire, en privé et chiffré. Il a été construit par Rich et un grand nombre d'agents patients, surtout en s'utilisant lui-même. Il est en pré-alpha fermée, donc il est un peu brut par endroits. Si ça te tente, demande gentiment et tu pourras entrer plus tôt que les autres."]}],"quips":{"1":"Un mot. Audacieux. Peut-être trop.","3":"Trois mots. Déjà plus honnête que la plupart des pages produit.","8":"Huit mots. Encore plus court qu'une réunion debout.","21":"Les longueurs sont des story points, au fait. Évidemment.","55":"Cinquante-cinq mots. Deux cartes ont été terminées pendant ta lecture.","144":"Voilà la longue. Il n'y a pas de 233. Les agents sont allés se coucher."}},"timeline":{"first-idea.name":"La première idée","first-idea.line":"La toute première conversation, avant la moindre ligne de code.","first-board.name":"Premier tableau","first-board.line":"Un tableau qui suit sa propre construction : cartes, colonnes, glisser-déposer, projets.","team-roles.name":"Équipe et rôles","team-roles.line":"Profils d'agents, modèles d'équipe, espaces et qui fait quoi.","install.name":"Installation et versions","install.line":"Un zip qu'un ami peut installer, mises à jour automatiques, canaux et retour en arrière.","usage-saver.name":"Économie d'usage","usage-saver.line":"Mesurer ce que coûtent les exécutions, garder le code léger, préserver ta limite.","friends.name":"Amis et partage","friends.line":"Messages privés, relais brouillé, invitations, rôles et projets partagés.","languages.name":"Langues","languages.line":"Chaque texte d'écran dans un fichier de langue, avec le néerlandais et le flamand en premier.","ai-tester.name":"Testeur IA","ai-tester.line":"Un testeur vérifie chaque remise d'abord et montre ce qu'il a vu.","website.name":"Le site web","website.line":"aigile.lol, la page teaser et cette chronologie.","streaming.name":"Chat et streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF et emojis.","no-ai.name":"Édition sans IA","no-ai.line":"Un tableau pour ceux qui codent sans IA, et des tableaux publics.","night-watch.name":"Veille de nuit","night-watch.line":"Un veilleur et un Scrum Master gardent les équipes sur la tâche pendant que tu dors.","p-more.name":"Tout le reste","p-more.line":"Des idées plus petites qui attendent encore leur tour.","p-android.name":"Téléphone et Android","p-android.line":"Accéder à ton tableau depuis un téléphone, puis une appli Android native.","p-release.name":"Alpha et après","p-release.line":"Alpha fermée, le site en ligne, puis la bêta.","p-languages.name":"Plus de langues","p-languages.line":"Plus d'une centaine de langues, et un mode immersion pour ceux qui apprennent.","p-engines.name":"Plus de moteurs IA","p-engines.line":"Choisis Claude, Codex ou Gemini pour chaque agent.","p-pro.name":"Pratiques pro","p-pro.line":"Étiquettes de risque, barrières de fusion, cartes d'incident et garde-fous.","p-self.name":"Prendre soin de toi","p-self.line":"Mode fatigué, rappels de bien-être et 4:20.","p-servers.name":"Serveurs et échelle","p-servers.line":"Réglages de serveur globaux, rôles et préparation de la croissance.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat Twitch, emojis personnalisés et vue publique en direct."}};
